<div class="flex items-center gap-2 pt-1">
<button class="flex-1 h-11 rounded-xl bg-primary-container hover:bg-primary text-on-primary font-label-md text-label-md flex items-center justify-center gap-1.5 active:scale-[0.98] transition-all" onclick="executeFinalSubmit()" type="button">
<span class="material-symbols-outlined text-[18px]">check_circle</span>
        Ya, Konfirmasi &amp; Simpan
      </button>
<button class="px-4 h-11 rounded-xl bg-surface-container text-on-surface hover:bg-surface-container-high font-label-sm text-label-sm transition-all" onclick="scrollBackToCalc()" type="button">
        Periksa Kembali
      </button>
</div>
